<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#25212a;font-size:10px}h1{margin:0;color:#ff6b35}.meta{margin:8px 0 20px;color:#746e78}.summary{display:flex;gap:20px;margin-bottom:18px}.summary div{border:1px solid #ddd;padding:9px}table{width:100%;border-collapse:collapse}th,td{padding:7px;border:1px solid #ddd;text-align:left}th{background:#f5f2f5}</style></head><body><h1>myhourspay</h1><h2>{{ $workspace->name }} · Hours report</h2><div class="meta">{{ $user->name }} · {{ $start->format('d M Y') }}–{{ $end->format('d M Y') }}</div><div class="summary"><div><strong>Total</strong><br>{{ $summary['total_formatted'] }}</div><div><strong>Overtime</strong><br>{{ $summary['overtime_formatted'] }}</div><div><strong>Paid breaks</strong><br>{{ $summary['paid_break_formatted'] }}</div><div><strong>Unpaid breaks</strong><br>{{ $summary['unpaid_break_formatted'] }}</div></div><table><thead><tr><th>Date</th><th>Time</th><th>Break</th><th>Hours</th><th>Overtime</th><th>Notes</th></tr></thead><tbody>@foreach($summary['entries'] as $entry)<tr><td>{{ $entry['work_date'] }}</td><td>{{ $entry['start_time'] }}–{{ $entry['end_time'] }}</td><td>{{ ucfirst($entry['break_type']) }} · {{ $entry['break_minutes'] }}m</td><td>{{ $entry['net_formatted'] }}</td><td>{{ $entry['weekly_overtime_formatted'] }}</td><td>{{ $entry['notes'] }}</td></tr>@endforeach</tbody></table></body></html>
